
CREATE TABLE `mp_interface`
(
    `pk`               bigint(20) unsigned NOT NULL AUTO_INCREMENT,
    `id`               varchar(64)         NOT NULL COMMENT '平台id',
    `ip`               varchar(64)         NOT NULL COMMENT 'ip或域名',
    `path`             varchar(512)        NOT NULL COMMENT '路径',
    `desc`             varchar(512)        NOT NULL COMMENT '描述',
    `create_time`      datetime            NOT NULL COMMENT '创建时间',
    `update_time`      datetime            NOT NULL COMMENT '更新时间',
    PRIMARY KEY (`pk`),
    UNIQUE KEY (`id`)
) COMMENT ='接口管理表';

